CREATE OR REPLACE FUNCTION private.voom_marketplace_my_subscriptions_impl()
 RETURNS TABLE(id uuid, strategy_id uuid, strategy_version text, account_session_id uuid, status text, risk_profile text, approved_for_live boolean, created_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception 'authentication_required' using errcode = '28000';
  end if;
  if not exists (
    select 1 from public.customer_profiles p
    where p.user_id = v_user_id and p.account_status = 'active' and p.role = 'customer'
  ) then
    raise exception 'active_customer_required' using errcode = '42501';
  end if;
  return query
  select sub.id, sub.strategy_id, sub.strategy_version, sub.account_session_id,
         sub.status, sub.risk_profile, sub.approved_for_live, sub.created_at, sub.updated_at
  from public.customer_ai_subscriptions sub
  where sub.user_id = v_user_id
  order by sub.created_at desc
  limit 100;
end;
$function$

CREATE OR REPLACE FUNCTION private.voom_marketplace_pause_impl(p_subscription_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_user_id uuid := auth.uid();
 v_updated public.customer_ai_subscriptions%rowtype;
begin
 if v_user_id is null then
   raise exception 'authentication_required' using errcode = '28000';
 end if;
 if not exists (
   select 1 from public.customer_profiles p
   where p.user_id = v_user_id and p.account_status = 'active' and p.role = 'customer'
 ) then
   raise exception 'active_customer_required' using errcode = '42501';
 end if;
 update public.customer_ai_subscriptions sub
 set status = 'paused', updated_at = now()
 where sub.id = p_subscription_id and sub.user_id = v_user_id
   and sub.status in ('pending','paper_active','demo_active')
 returning * into v_updated;
 if not found then
   raise exception 'active_subscription_not_found' using errcode = 'P0002';
 end if;
 return jsonb_build_object('id',v_updated.id,'status',v_updated.status,
   'mode','paper_only','order_execution','disabled');
end;
$function$

CREATE OR REPLACE FUNCTION private.voom_marketplace_subscribe_impl(p_strategy_id uuid, p_account_session_id uuid DEFAULT NULL::uuid, p_risk_profile text DEFAULT 'moderate'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 v_user_id uuid := auth.uid();
 v_strategy public.ai_strategies%rowtype;
 v_session public.trading_sessions%rowtype;
 v_existing public.customer_ai_subscriptions%rowtype;
 v_new public.customer_ai_subscriptions%rowtype;
begin
 if v_user_id is null then raise exception 'authentication_required' using errcode = '28000'; end if;
 if not exists (select 1 from public.customer_profiles p where p.user_id=v_user_id and p.account_status='active' and p.role='customer') then
   raise exception 'active_customer_required' using errcode = '42501';
 end if;
 if p_risk_profile not in ('conservative','moderate','aggressive') then raise exception 'invalid_risk_profile' using errcode = '22023'; end if;
 select * into v_strategy from public.ai_strategies s
 where s.id=p_strategy_id and s.lifecycle_status='approved' and s.trading_mode in ('paper','demo')
   and s.backtest_passed and s.out_of_sample_passed and s.demo_passed and s.risk_review_passed;
 if not found then raise exception 'strategy_not_approved_for_paper_or_demo' using errcode = '42501'; end if;
 if p_account_session_id is not null then
   select * into v_session from public.trading_sessions t where t.id=p_account_session_id and t.user_id=v_user_id;
   if not found then raise exception 'session_not_owned_by_customer' using errcode = '42501'; end if;
   if v_session.environment='live' then raise exception 'live_sessions_not_supported' using errcode = '42501'; end if;
 end if;
 perform pg_advisory_xact_lock(hashtextextended(v_user_id::text || ':' || p_strategy_id::text || ':' || coalesce(p_account_session_id::text,'no-session'),0));
 select * into v_existing from public.customer_ai_subscriptions sub
 where sub.user_id=v_user_id and sub.strategy_id=p_strategy_id
   and sub.account_session_id is not distinct from p_account_session_id
   and sub.status in ('pending','paper_active','demo_active') limit 1;
 if found then raise exception 'subscription_already_active' using errcode = '23505'; end if;
 -- Reuse the customer's paused row to respect the unique key and preserve audit history.
 select * into v_existing from public.customer_ai_subscriptions sub
 where sub.user_id=v_user_id and sub.strategy_id=p_strategy_id
   and sub.account_session_id is not distinct from p_account_session_id
   and sub.status='paused' order by sub.updated_at desc limit 1;
 if found then
   update public.customer_ai_subscriptions sub
   set status='paper_active', strategy_version=v_strategy.version, risk_profile=p_risk_profile,
       approved_for_live=false, updated_at=now()
   where sub.id=v_existing.id returning * into v_new;
   return jsonb_build_object('id',v_new.id,'strategy_id',v_new.strategy_id,'strategy_version',v_new.strategy_version,
     'account_session_id',v_new.account_session_id,'status',v_new.status,'risk_profile',v_new.risk_profile,
     'approved_for_live',false,'mode','paper_only','order_execution','disabled');
 end if;
 insert into public.customer_ai_subscriptions(user_id,strategy_id,strategy_version,account_session_id,status,risk_profile,approved_for_live)
 values(v_user_id,v_strategy.id,v_strategy.version,p_account_session_id,'paper_active',p_risk_profile,false)
 returning * into v_new;
 return jsonb_build_object('id',v_new.id,'strategy_id',v_new.strategy_id,'strategy_version',v_new.strategy_version,
   'account_session_id',v_new.account_session_id,'status',v_new.status,'risk_profile',v_new.risk_profile,
   'approved_for_live',false,'mode','paper_only','order_execution','disabled');
end;
$function$
